        #region Project Application Recieved List
        [HttpGet]
        public ActionResult ProjectInfoDesk()
        {
            ClsMethod_Helpdesk sdb = new ClsMethod_Helpdesk();
            ClsMethod_View_ProjectWorkingFilesHelpdesk sdbWorkFile = new ClsMethod_View_ProjectWorkingFilesHelpdesk();
            ClsPrp_AuthorityDesk_ProjectDiaryNumber aa = new ClsPrp_AuthorityDesk_ProjectDiaryNumber();
            ClsPrp_AuthorityDesk_ProjectDiaryNumberToExcel aaXls = new ClsPrp_AuthorityDesk_ProjectDiaryNumberToExcel();

            string userRole = string.Empty;
            aa.prpongoing = sdb.Display_AuthorityDesk_ProjectDetails(userRole);
            var mirrorWorkFileCheckList = sdbWorkFile.Display_AuthorityDesk_ProjectWorkingFileDetailsCheckList(string.Empty);
            MergeProjectDiaryMirror(aa.prpongoing, mirrorWorkFileCheckList);

            foreach (var item in aa.prpongoing)
            {
                ClsPrp_AuthorityDesk_ProjectDiaryNumberToExcel aaXlsInner = new ClsPrp_AuthorityDesk_ProjectDiaryNumberToExcel();

                aaXlsInner.Project_DiaryNumber = item.PromoterRegDiaryNumber_Name;
                aaXlsInner.Application_Date = item.CreatedOn;
                aaXlsInner.Project_Name = item.Project_Name;
                aaXlsInner.ProjectAddress_District = item.Project_AddressDistrictName;
                aaXlsInner.Promoter_Name = item.Promoter_Name;
                aaXlsInner.Status = item.EventAction_Aggregate;
                aaXlsInner.Status_Date = item.EventAction_IdentifiedOn;
                aaXls.prpongoing.Add(aaXlsInner);
            }
            Session["modelInProcessApplicationsforProjectMIS"] = aaXls.prpongoing;
            return View("ProjectInfoDesk", aa);
        }

