        [HttpGet]
        public ActionResult ProjectInfoDeskRegRERAnumberDetails()
        {
            return BindProjectInfoDeskRegRERAnumberDetails(DateTime.Now.Year, null, null, "year", string.Empty);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult ProjectInfoDeskRegRERAnumberDetails(int? approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            return BindProjectInfoDeskRegRERAnumberDetails(approvalyear, fromDate, toDate, filterType, rangeLabel);
        }

        private ActionResult BindProjectInfoDeskRegRERAnumberDetails(int? approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            ClsMethod_ViewAdd_ProjectRERAnumber sdb = new ClsMethod_ViewAdd_ProjectRERAnumber();
            ClsMethod_View_ProjectWorkingFilesHelpdesk sdbWorkFile = new ClsMethod_View_ProjectWorkingFilesHelpdesk();
            ClsPrp_AuthorityDesk_ProjectRERAnumberDetails aa = new ClsPrp_AuthorityDesk_ProjectRERAnumberDetails();
            ClsPrp_AuthorityDesk_ProjectRERAnumberDetailsToExcel aaXls = new ClsPrp_AuthorityDesk_ProjectRERAnumberDetailsToExcel();

            string userRole = string.Empty;
            //aa.prpongoing = sdb.Display_AuthDesk_ProjectRERAnumberDiaryNumberDashBoard_ByUserID(userRole);
            if (filterType == "all")
            {
                aa.prpongoing = sdb.Display_AuthDesk_ProjectRERAnumberDiaryNumberDashBoard_ByUserID(userRole);
            }
            else
                aa.prpongoing = sdb.Display_AuthDesk_ProjectRERAnumberDiaryNumberDashBoard_ByDate(approvalyear, fromDate, toDate, filterType, userRole);

            foreach (var item in aa.prpongoing)
            {
                ClsPrp_AuthorityDesk_ProjectRERAnumberDetailsToExcel aaXlsInner = new ClsPrp_AuthorityDesk_ProjectRERAnumberDetailsToExcel();

                aaXlsInner.Project_DiaryNumber = item.ProjectRegDiaryNumber_Name;
                aaXlsInner.Application_Date = item.CreatedOn;
                aaXlsInner.Project_Name = item.Project_Name;
                aaXlsInner.Promoter_Name = item.Promoter_Name;
                aaXlsInner.Project_AddressDistrictName = item.Project_AddressDistrictName;
                aaXlsInner.ProjectPotentialZone = item.ProjectPotentialZone;
                aaXlsInner.RERA_Registration_Number = item.RERAnumberRegistration;
                aaXlsInner.RERA_Number_IssueDate = item.RERAnumberIssueDate;
                aaXlsInner.RERA_Number_RegistrationUptoDate = item.RERAnumberRegUptoDate;
                aaXlsInner.Status = item.EventAction_Aggregate;
                aaXlsInner.Status_Date = item.EventAction_IdentifiedOn;
                aaXls.prpongoing.Add(aaXlsInner);
            }
            Session["modelProjectsInPublicViewMIS"] = aaXls.prpongoing;
            ViewBag.Years = GetApprovalYears();
            ViewBag.SelectedApprovalYear = approvalyear;
            ViewBag.FromDate = fromDate.HasValue ? fromDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.ToDate = toDate.HasValue ? toDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.SelectedRangeLabel = rangeLabel ?? string.Empty;
            ModelState.Clear();
            return View("ProjectInfoDeskRegRERAnumberDetails", aa);
        }


