                workSheet.Cells[recordIndex, 11].Value = PCCcodeItem.PCC_ReferenceDate.HasValue ? (PCCcodeItem.PCC_ReferenceDate.Value.ToString("dd-MMM-yyyy") == "01-Jan-0001" ? string.Empty : PCCcodeItem.PCC_ReferenceDate.Value.ToString("dd-MMM-yyyy")) : string.Empty;

                workSheet.Row(recordIndex).Height = 15;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();

            workSheet.Cells["A1:K1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:K1"].Style.Fill.BackgroundColor.SetColor(Color.Yellow);

            using (ExcelRange RangePCC = workSheet.Cells[1, 1, recordIndex - 1, 11])
            {
                RangePCC.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Top.Color.SetColor(Color.Black);
                RangePCC.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Left.Color.SetColor(Color.Black);
                RangePCC.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Right.Color.SetColor(Color.Black);
                RangePCC.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangePCC.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangePCC.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofProjectCompletionCertificate_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }
