        [HttpGet]
        public ActionResult ProjectExtensionInfoDeskApproved() // initial load always defaults to Initial Extension Application (6)
        {
            //return BindProjectExtensionInfoDeskApproved(1);
            int applicationType = 1; // Always default to All

            if (TempData["ApplicationType"] != null)
            {
                applicationType = Convert.ToInt32(TempData["ApplicationType"]);
            }

            return BindProjectExtensionInfoDeskApproved(applicationType);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult ProjectExtensionInfoDeskApproved(int applicationType) // 1 = All, 6 = Initial Extension Application, 8 = Additional Extension Application
        {
            //return BindProjectExtensionInfoDeskApproved(applicationType);
            TempData["ApplicationType"] = applicationType;

            return RedirectToAction("ProjectExtensionInfoDeskApproved");
        }

        private ActionResult BindProjectExtensionInfoDeskApproved(int applicationType)
        {
            ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
            ClsPrp_ExtensionAuthorityDesk_ProjectDiaryNumber aa = new ClsPrp_ExtensionAuthorityDesk_ProjectDiaryNumber();
            ClsPrp_ExtensionAuthorityDesk_ProjectDiaryNumberToExcel aaXls = new ClsPrp_ExtensionAuthorityDesk_ProjectDiaryNumberToExcel();
            string userRole = string.Empty;

            aa.prpongoing = sdb.Display_AuthorityDesk_ProjectExtensionDetailsApprovedByApplicationType(applicationType);

            foreach (var item in aa.prpongoing)
            {
                ClsPrp_ExtensionAuthorityDesk_ProjectDiaryNumberToExcel aaXlsInner = new ClsPrp_ExtensionAuthorityDesk_ProjectDiaryNumberToExcel();
                aaXlsInner.Project_RegistrationNumber = item.Project_RERAregistrationNumber;
                aaXlsInner.Project_DiaryNumber = item.ProjectExtForm_RegDiaryNumber_Name;
                aaXlsInner.Application_Date = item.ProjectExtensionApplicationDate;
                aaXlsInner.Project_Name = item.Project_Name;
                aaXlsInner.ProjectAddress_District = item.Project_AddressDistrictName;
                aaXlsInner.Promoter_Name = item.Promoter_Name;
                aaXlsInner.Status = item.EventAction_Aggregate;
                aaXlsInner.Status_Date = item.EventAction_IdentifiedOn;
                aaXls.prpongoing.Add(aaXlsInner);
            }

            Session["modelApprovedApplicationsforExtnProjectMIS"] = aaXls.prpongoing;

            ViewBag.ApplicationTypeList = new SelectList(new List<SelectListItem>
            {
                new SelectListItem { Text = "All", Value = "1" },
                new SelectListItem { Text = "First Application", Value = "6" },
                new SelectListItem { Text = "Additional Application", Value = "8" }
            }, "Value", "Text", applicationType);
            ViewBag.SelectedApplicationType = applicationType;

            ModelState.Clear();
            return View("ProjectExtensionInfoDeskApproved", aa);
        }



