        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult ProjectExtensionInfoDeskRegRERAnumberDetails(int? approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            return BindProjectExtensionInfoDeskRegRERAnumberDetails(approvalyear, fromDate, toDate, filterType, rangeLabel);
        }

        private ActionResult BindProjectExtensionInfoDeskRegRERAnumberDetails(int? approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            ClsExtnMethod_ProjectExtensionRERAnumber sdb = new ClsExtnMethod_ProjectExtensionRERAnumber();
            ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumber aa = new ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumber();
            ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumberToExcel aaXls = new ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumberToExcel();

            string userRole = string.Empty;
            //aa.prpongoing = sdb.Display_AuthorityDesk_ProjectExtnFormRegistrationNumberDetails(userRole);
            //aa.prpongoing = sdb.Display_AuthorityDesk_ProjectExtnFormRegistrationNumberDetails(userRole);
            if (filterType == "all")
            {
                aa.prpongoing = sdb.Display_AuthorityDesk_ProjectExtnFormRegistrationNumberDetails(userRole);
            }
            else
            {
                aa.prpongoing = sdb.Display_AuthorityDesk_ProjectExtnFormRegistrationNumberDetailsByDate(approvalyear, filterType, fromDate, toDate, userRole);
            }
            foreach (var item in aa.prpongoing)
            {
                ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumberToExcel aaXlsInner = new ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumberToExcel();

                aaXlsInner.RelatedExtnRegDiaryNumber_Name = item.RelatedExtnRegDiaryNumber_Name;
                aaXlsInner.ProjectExtensionApplicationDate = item.ProjectExtensionApplicationDate;
                aaXlsInner.Project_Name = item.Project_Name;
                aaXlsInner.Promoter_Name = item.Promoter_Name;
                aaXlsInner.Project_AddressDistrictName = item.Project_AddressDistrictName;
                aaXlsInner.ProjectPotentialZone = item.ProjectPotentialZone;
                aaXlsInner.RERAnumberRegistration = item.RERAnumberRegistration;
                aaXlsInner.RERAnumberIssueDate = item.RERAnumberIssueDate;
                aaXlsInner.RERAnumberRegUptoDate = item.RERAnumberRegUptoDate;
                aaXlsInner.ExtnRegistrationRegUptoDate = item.ExtnRegistrationRegUptoDate;
                aaXlsInner.EventAction_Aggregate = item.EventAction_Aggregate;
                aaXlsInner.EventAction_IdentifiedOn = item.EventAction_IdentifiedOn;
                aaXls.prpongoing.Add(aaXlsInner);
            }
            Session["modelExtensionProjectsInPublicViewMIS"] = aaXls.prpongoing;
            ViewBag.Years = GetApprovalYears();
            ViewBag.SelectedApprovalYear = approvalyear;
            ViewBag.FromDate = fromDate.HasValue ? fromDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.ToDate = toDate.HasValue ? toDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.SelectedRangeLabel = rangeLabel ?? string.Empty;
            ModelState.Clear();
            return View("ProjectExtensionInfoDeskRegRERAnumberDetails", aa);
        }

        public void ExtensionProjectsInPublicView_ExportToExcel()
        {
            var objXlslist = Session["modelExtensionProjectsInPublicViewMIS"] as List<ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumberToExcel>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");
            workSheet.TabColor = System.Drawing.Color.Black;
            workSheet.DefaultRowHeight = 12;

            //Header of table
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "Registration Number";
            workSheet.Cells[1, 3].Value = "Registration Issue Date";
            workSheet.Cells[1, 4].Value = "Registration Valid Upto Date";
            workSheet.Cells[1, 5].Value = "Extension of Registration Valid Upto Date";
            workSheet.Cells[1, 6].Value = "Project Name";
            workSheet.Cells[1, 7].Value = "Promoter Name";
            workSheet.Cells[1, 8].Value = "Project District Name";
            workSheet.Cells[1, 9].Value = "Project Zone";
            workSheet.Cells[1, 10].Value = "Diary Number";
            workSheet.Cells[1, 11].Value = "Application Date";
            workSheet.Cells[1, 12].Value = "Status";
            workSheet.Cells[1, 13].Value = "Status Date";
            workSheet.Cells[1, 14].Value = "Remarks, if Any";

            //Body of table  
            int recordIndex = 2;
            string retDateValue = string.Empty;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.RERAnumberRegistration;
                if (QRcodeItem.RERAnumberRegistration != "NA")
                {
                    workSheet.Cells[recordIndex, 3].Value = QRcodeItem.RERAnumberIssueDate.HasValue ? (QRcodeItem.RERAnumberIssueDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.RERAnumberIssueDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                    workSheet.Cells[recordIndex, 4].Value = QRcodeItem.RERAnumberRegUptoDate.HasValue ? (QRcodeItem.RERAnumberRegUptoDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.RERAnumberRegUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                }
                else
                {
                    workSheet.Cells[recordIndex, 3].Value = string.Empty;
                    workSheet.Cells[recordIndex, 4].Value = string.Empty;
                }
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.ExtnRegistrationRegUptoDate.HasValue ? (QRcodeItem.ExtnRegistrationRegUptoDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.ExtnRegistrationRegUptoDate.Value.ToString("dd-MMM-yyyy") : "NA") : string.Empty;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.Project_Name;
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.Promoter_Name;
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.Project_AddressDistrictName;
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.ProjectPotentialZone != "NA" ? string.Concat("Zone-", QRcodeItem.ProjectPotentialZone) : QRcodeItem.ProjectPotentialZone;
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.RelatedExtnRegDiaryNumber_Name;
                workSheet.Cells[recordIndex, 11].Value = QRcodeItem.ProjectExtensionApplicationDate.HasValue ? QRcodeItem.ProjectExtensionApplicationDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 12].Value = QRcodeItem.EventAction_Aggregate;
                workSheet.Cells[recordIndex, 13].Value = QRcodeItem.EventAction_IdentifiedOn.HasValue ? QRcodeItem.EventAction_IdentifiedOn.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 14].Value = string.Empty;

                workSheet.Row(recordIndex).Height = 15;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();
            workSheet.Column(13).AutoFit();
            workSheet.Column(14).AutoFit();

            workSheet.Cells["A1:N1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:N1"].Style.Fill.BackgroundColor.SetColor(ColorTranslator.FromHtml("#7bb73f"));

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 14])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofExtensionProjectsInPublicView_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }

