        #region Form-E or Project Extensions Event 

        [HttpGet]
        public ActionResult ProjectExtensionInfoEventInsert()//Int64 projectId, string DiaryNumber)
        {
            ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
            ClsPrp_ExtensionAuthorityDesk_ProjectEventLog aa = new ClsPrp_ExtensionAuthorityDesk_ProjectEventLog();

            string userRole = string.Empty;
            userRole = getUserRole();
            //to bind subCheckList master
            aa.EventMaster = sdb.Display_AuthorityDesk_ProjectExtensionEvent_Master(userRole);

            if (Session["zipExtensionProjectDiaryNumber"] != null)
            {
                string ExtensionProjectDiaryNumber = Session["zipExtensionProjectDiaryNumber"].ToString();
                string ExtensionProjectName = Session["zipExtensionProjectName"].ToString();
                Int64? ExtensionProjectID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                DateTime? ExtensionLastModifiedOn = Convert.ToDateTime(Session["zipExtensionLastModifiedOn"]);
                Int64? ExtensionPromoterID = Convert.ToInt64(Session["zipExtensionPromoterID"]);

                aa.Related_Promoter_ID = (ExtensionPromoterID != null) ? Convert.ToInt64(ExtensionPromoterID) : 0;
                aa.Related_Project_ID = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
                aa.Promoter_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                aa.Project_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                aa.ProjectName = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
                aa.ProjectLastModifiedOn = ExtensionLastModifiedOn;
            }
            else
            {
                aa.Related_Promoter_ID = 0;
                aa.Related_Project_ID = 0;
                aa.Promoter_DiaryNumber = "";
                aa.Project_DiaryNumber = "";
                aa.ProjectName = "";
            }
            TempData["ExtensionFormEventSubmitMessage"] = "";

            return View("ProjectExtensionInfoEventInsert", aa);
        }

        [HttpGet]
        public ActionResult ProjectExtensionInfoEventInsertAction(string ExtensionProjectDiaryNumber, string ExtensionProjectName, Int64? ExtensionProjectID, DateTime? ExtensionLastModifiedOn, Int64? ExtensionPromoterID)
        {

            Session["zipExtensionProjectDiaryNumber"] = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
            Session["zipExtensionProjectName"] = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
            Session["zipExtensionProjectID"] = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
            Session["zipExtensionLastModifiedOn"] = ExtensionLastModifiedOn;
