        [HttpPost]
        public ActionResult ProjectExtensionInfoEventInsert(ClsPrp_ExtensionAuthorityDesk_ProjectEventLog smodel)
        {
            ClsPrp_ExtensionAuthorityDesk_ProjectEventLog aa = new ClsPrp_ExtensionAuthorityDesk_ProjectEventLog();
            try
            {
                if (ModelState.IsValid)
                {
                    ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
                    string pUserRole = getUserRole();
                    string pUser_WhoIdentified = User.Identity.Name;

                    if (sdb.Add_ProjectExtensionForm_InfoEvent(smodel, pUserRole, pUser_WhoIdentified))
                    {
                        ViewBag.Message = "Details Added Successfully";
                        ModelState.Clear();

                        TempData["ExtensionFormEventSubmitMessage"] = "Application Performa successfully Submitted.";
                        TempData["ExtensionFormEventSubmitMessageMappingUrlFlag"] = getMappingUrlByProjectExtensionEvent();

                        // redirect to the node you came from (listing), keeping parameters intact
                        var originKey = (Session["currentNodeKey"] as string) ?? "Helpdesk_ProjectExtensionInfoDesk";
                        // return Redirect(GetUrlFromSiteMapKey(originKey));
                    }
                }

                // re-bind dropdowns etc when not redirecting
                {
                    ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
                    string pUserRole = getUserRole();
                    aa.EventMaster = sdb.Display_AuthorityDesk_ProjectExtensionEvent_Master(pUserRole);

                    if (Session["zipExtensionProjectDiaryNumber"] != null)
                    {
                        string ExtensionProjectDiaryNumber = Session["zipExtensionProjectDiaryNumber"].ToString();
                        string ExtensionProjectName = Session["zipExtensionProjectName"].ToString();
                        long? ExtensionProjectID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                        DateTime? ExtensionLastModifiedOn = Convert.ToDateTime(Session["zipExtensionLastModifiedOn"]);
                        long? ExtensionPromoterID = Convert.ToInt64(Session["zipExtensionPromoterID"]);

                        aa.Related_Promoter_ID = ExtensionPromoterID ?? 0;
                        aa.Related_Project_ID = ExtensionProjectID ?? 0;
                        aa.Promoter_DiaryNumber = ExtensionProjectDiaryNumber ?? "";
                        aa.Project_DiaryNumber = ExtensionProjectDiaryNumber ?? "";
                        aa.ProjectName = ExtensionProjectName ?? "";
                        aa.ProjectLastModifiedOn = ExtensionLastModifiedOn;
                    }
                    else
                    {
                        aa.Related_Promoter_ID = 0;
                        aa.Related_Project_ID = 0;
                        aa.Promoter_DiaryNumber = "";
                        aa.Project_DiaryNumber = "";
                        aa.ProjectName = "";
                    }
                }

                return View("ProjectExtensionInfoEventInsert", aa);
            }
            catch
            {
                TempData["ExtensionFormEventSubmitMessage"] = "Sorry, Application Performa is pending";
                TempData["ExtensionFormEventSubmitMessageMappingUrlFlag"] = getMappingUrlByProjectExtensionEvent();
                return View("ProjectExtensionInfoEventInsert", aa);
            }
        }

