        [HttpGet]
        public ActionResult ProjectFormExtensionInfoCheckListDisplay()
        {
            ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
            ClsPrp_ExtensionAuthorityDesk_ProjectSubCheckListLog aa = new ClsPrp_ExtensionAuthorityDesk_ProjectSubCheckListLog();
            string userRole = string.Empty;
            Int64 ProjectID = 0;
            userRole = getUserRole();
            if (Session["zipExtensionProjectDiaryNumber"] != null)
            {
                Int64? ExtensionProjectID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                ProjectID = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
            }

            aa.prpongoing = sdb.Display_FormExtension_AuthorityDesk_CheckList_DetailsByCode(ProjectID, userRole);

            foreach (var item in aa.prpongoing)
            {
                aa.ProjectExtensionCheckListAction_ID = item.ProjectExtensionCheckListAction_ID;
                aa.CheckList_IdentifiedBy = item.CheckList_IdentifiedBy;
                aa.UserRole = item.UserRole;
                aa.CheckList_IdentifiedOn = item.CheckList_IdentifiedOn;
                aa.Related_Promoter_ID = item.Related_Promoter_ID;
                aa.Related_Project_ID = item.Related_Project_ID;
                aa.Promoter_DiaryNumber = item.Promoter_DiaryNumber;
                aa.Project_DiaryNumber = item.Project_DiaryNumber;
