        #region View Extension Form-E Details
        [HttpGet]
        public ActionResult Display_ProjectExtensionForm()
        {
            ClsMethod_View_ExtensionProjectExtensionFormDetails sdb = new ClsMethod_View_ExtensionProjectExtensionFormDetails();
            ClsPrp_AuthDesk_View_ExtensionProjectExtensionFormDetails aa = new ClsPrp_AuthDesk_View_ExtensionProjectExtensionFormDetails();

            ClsMethod_View_ProjectDocuments sdbpdoclist = new ClsMethod_View_ProjectDocuments();

            string userRole = string.Empty;
            Int64 ProjectID = 0;
            userRole = getUserRole();
            if (Session["zipExtensionProjectDiaryNumber"] != null)
            {
                Int64? Project_ID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                ProjectID = (Project_ID != null) ? Convert.ToInt64(Project_ID) : 0;
            }

            aa.prpongoing = sdb.Display_Project_ExtensionFormDetails(ProjectID);
            aa.ProjectDocumentsList = sdbpdoclist.Display_Project_Documents_ByProjectId(ProjectID);


            #region Lock - Unlock (Logic Display Message)
            bool var_Anydocopen = false;
            bool var_Alldocclosed = false;
            bool var_Anydocpermanent = false;

            if (aa.prpongoing.Count == 0)
            {
                aa.IsDraftAllextensionformwithdocuments = 0;
            }

            foreach (var item in aa.prpongoing)
            {
                aa.FormE_IndexID = item.FormE_IndexID;
                aa.FormE_ID = item.FormE_ID;
                aa.Promoter_ID = item.Promoter_ID;
                aa.Project_ID = item.Project_ID;

                aa.ProjectExtension_NameID = item.ProjectExtension_NameID;
                aa.ProjectExtension_NameYear = item.ProjectExtension_NameYear;
                aa.ProjectExtension_Name = item.ProjectExtension_Name;
                aa.Project_DiaryNumberID = item.Project_DiaryNumberID;
                aa.Project_RERAnumber = item.Project_RERAnumber;
                aa.Project_RERANumberIssueDate = item.Project_RERANumberIssueDate;
                aa.Project_RERANumberValiduptoDate = item.Project_RERANumberValiduptoDate;
                aa.FormE_DocIssueDate = item.FormE_DocIssueDate;
                aa.FormE_ExtensionAppliedReason = item.FormE_ExtensionAppliedReason;
                aa.FormE_ExtensionAppliedReasonSpecifyOthers = item.FormE_ExtensionAppliedReasonSpecifyOthers;

                aa.FormE_DocInfoCode = item.FormE_DocInfoCode;
                aa.FormE_DocInfoName = item.FormE_DocInfoName;
                aa.IsActive = item.IsActive;
                aa.IsDraft = item.IsDraft;

                if (item.IsDraft == 1)
                {
                    var_Alldocclosed = true;
                }
                if (item.IsDraft == 5)
                {
                    var_Anydocopen = true;
                }
                if (item.IsDraft == 6)
                {
                    var_Anydocpermanent = true;
                }
            }

            if (var_Anydocpermanent)
            {
                aa.IsDraftAllextensionformwithdocuments = 6;
            }
            else if (var_Anydocopen)
            {
                aa.IsDraftAllextensionformwithdocuments = 5;
            }
            else if (var_Alldocclosed)
            {
                aa.IsDraftAllextensionformwithdocuments = 1;
            }
            else
            {
                aa.IsDraftAllextensionformwithdocuments = 0;
            }
            #endregion

            if (Session["zipExtensionProjectDiaryNumber"] != null)
            {
                string ExtensionProjectDiaryNumber = Session["zipExtensionProjectDiaryNumber"].ToString();
                string ExtensionProjectName = Session["zipExtensionProjectName"].ToString();
                Int64? ExtensionProject_ID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                DateTime? ExtensionLastModifiedOn = Convert.ToDateTime(Session["zipExtensionLastModifiedOn"]);
                Int64? ExtensionPromoterID = Convert.ToInt64(Session["zipExtensionPromoterID"]);

                aa.zipExtensionFormRelated_Promoter_ID = (ExtensionPromoterID != null) ? Convert.ToInt64(ExtensionPromoterID) : 0;
                aa.zipExtensionFormRelated_Project_ID = (ExtensionProject_ID != null) ? Convert.ToInt64(ExtensionProject_ID) : 0;
                aa.zipExtensionFormProject_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                aa.zipExtensionFormProjectName = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
                aa.zipExtensionFormProjectLastModifiedOn = ExtensionLastModifiedOn;
            }

            return View("Display_ProjectExtensionForm", aa);
        }

