        [HttpPost]
        public ActionResult Add_ExtensionProjectRegistrationNumber(ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumber smodel)
        {
            ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumber aa = new ClsPrp_ExtensionAuthorityDesk_ProjectExtnFormRegistrationNumber();
            ClsExtnMethod_ProjectExtensionRERAnumber sdb = new ClsExtnMethod_ProjectExtensionRERAnumber();
            ClsMethodDistrictMaster objdis = new ClsMethodDistrictMaster();

            string error = string.Empty;
            //int errorstate = 0;
            string UID = User.Identity.GetUserId();
            string UserNam = User.Identity.Name;
            string ProjectNam_DiaryNumber = string.Empty;
            string ExtnFormNam_DiaryNumber = string.Empty;
            Int64 ProjectNam_ID = 0;
            Int64 PromoterNam_ID = 0;

            aa.stateMaster = objdis.State_list();
            aa.districtMaster = objdis.dropdownlist_display1();

            if (Session["zipExtnProjectDiaryNumber"] != null)
            {
                string mmProjectDiaryNumber = Session["zipExtnProjectDiaryNumber"].ToString();
                string mmExtensionFormProjectDiaryNumber = Session["zipExtensionFormDiaryNumber"].ToString();
                Int64? mmExtnProjectID = Convert.ToInt64(Session["zipExtnProjectID"]);
                Int64? mmExtnPromoterID = Convert.ToInt64(Session["zipExtnPromoterID"]);

                PromoterNam_ID = (mmExtnPromoterID != null) ? Convert.ToInt64(mmExtnPromoterID) : 0;
                ProjectNam_ID = (mmExtnProjectID != null) ? Convert.ToInt64(mmExtnProjectID) : 0;
                ProjectNam_DiaryNumber = (String.IsNullOrEmpty(mmProjectDiaryNumber) ? "" : mmProjectDiaryNumber);
                ExtnFormNam_DiaryNumber = (String.IsNullOrEmpty(mmExtensionFormProjectDiaryNumber) ? "" : mmExtensionFormProjectDiaryNumber);
            }

            try
            {
                if (ModelState.IsValid)
                {
                    if (TempData["submitvalue"].ToString() == "Update")
                    {
                        if (sdb.Update_LDR_ProjectExtensionRegistrationNumber_DiaryNumber(smodel, UserNam, ProjectNam_ID, PromoterNam_ID, ProjectNam_DiaryNumber, ExtnFormNam_DiaryNumber))
                        {
                            TempData["Message"] = "Successfully Updated";
                            ModelState.Clear();
                        }
                        return RedirectToAction("Add_ExtensionProjectRegistrationNumber");
                    }
                    else
                    {
