                        {
                            ex.ToString();
                            return View();
                        }
                    }
                    return RedirectToAction("Add_ExtensionProjectRegistrationCertificate");
                }
                else
                {
                    return RedirectToAction("Add_ExtensionProjectRegistrationCertificate");
                }
            }
            else
            {
                #region PhotoCertificate Save with Path
                if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                {
                    var files = Request.Files[0];
                    var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg", ".PDF", ".pdf", ".Pdf" };
                    extractFileExt = Path.GetExtension(files.FileName); //getting the extension(ex-.jpg)  
                    if (allowedExtensions.Contains(extractFileExt)) //check what type of extension  
                    {
                        int size = files.ContentLength;
                        if (size <= 1024000)
                        {
                            #region Declare Variables
                            var pathpromoterdata = "";
                            var pathindb = "";
                            string masterAuthorityDoc_SetFilePath = "readwritePrjEnCert";
                            #endregion

                            #region SaveFile Path Creation
                            pathindb = masterAuthorityDoc_SetFilePath + "\\" + Convert.ToString(ccProjectID) + "\\";
                            pathpromoterdata = Server.MapPath("~/" + pathindb);

                            if (!Directory.Exists(pathpromoterdata))
                            {
                                Directory.CreateDirectory(pathpromoterdata);
                            }
                            #endregion

                            var fileName = string.Empty;
                            fileName = "EnPRJcert_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + extractFileExt;
                            var path = Path.Combine(pathpromoterdata, fileName);
                            files.SaveAs(path);
                            extractFileName = fileName;
                            extractFilePath = pathindb;
                            smodel.ProjectRERAcert_FileFormat = extractFileExt;
                        }
                        else
                        {
                            TempData["notice"] = "Document size should be less than 1MB";
                            error = "Document size should be less than 1MB";
                            errorstate = 1;
                        }
                    }
                    else
                    {
                        TempData["notice"] = "Document format should be .jpg or .pdf";
                        error = "Document format should be .jpg or .pdf";
                        errorstate = 1;
                    }
                }
                else
                {
                    TempData["notice"] = "Invalid! Please Upload Photograph";
                    error = "Invalid! Please Upload Photograph";
                    errorstate = 1;
                }
                #endregion
                try
                {
                    if (errorstate == 0)
                    {
                        if (ModelState.IsValid)
                        {
                            if (extractFileName == string.Empty)
                            {
                                extractFileName = smodel.ProjectRERAcert_FileName;
                                extractFileExt = smodel.ProjectRERAcert_FileFormat;
                                extractFilePath = smodel.ProjectRERAcert_FilePath;
                            }
                            ClsExtnMethod_ProjectExtensionRERAcertificate sdb = new ClsExtnMethod_ProjectExtensionRERAcertificate();
