        [HttpPost]
        public ActionResult ProjectInfoCheckListInsert(ClsPrp_AuthorityDesk_ProjectSubCheckListLog smodel)
        {
            string viewname = string.Empty;
            try
            {
                if (ModelState.IsValid)
                {
                    //var errors = ModelState.SelectMany(x => x.Value.Errors.Select(z => z.Exception));
                    ClsMethod_Helpdesk sdb = new ClsMethod_Helpdesk();

                    string pUserRole = string.Empty;
                    pUserRole = getUserRole();
                    string pUser_WhoIdentified = User.Identity.Name;
                    var existingChecklist = sdb.Display_AuthorityDesk_CheckList_DetailsByCode(smodel.Related_Project_ID, pUserRole);
                    var isDuplicateChecklist = existingChecklist != null && existingChecklist.Any(x =>
                        string.Equals((x.CriteriaCode ?? string.Empty).Trim(), (smodel.CriteriaCode ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase) &&
                        string.Equals((x.CriteriaSubCode ?? string.Empty).Trim(), (smodel.CriteriaSubCode ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase) &&
                        x.IsActive == 1);

                    if (isDuplicateChecklist)
                    {
                        TempData["EventSubmitMessage"] = "Checklist for selected criteria is already submitted for this project.";
                    }
                    else if (sdb.Add_Project_InfoCheckList(smodel, pUserRole, pUser_WhoIdentified))
                    {
                        ViewBag.Message = "Details Added Successfully";
                        ModelState.Clear();
                    }
                }


                var fullUrl = this.Request.UrlReferrer.ToString();
                string url = fullUrl;
                var request = new HttpRequest(null, url, null);
                var response = new HttpResponse(new System.IO.StringWriter());
                var httpContext = new HttpContext(request, response);
                var routeData = System.Web.Routing.RouteTable.Routes.GetRouteData(new HttpContextWrapper(httpContext));
                var values = routeData.Values;
                string controllerName = values["controller"].ToString();
                viewname = values["action"].ToString();

                return RedirectToAction(viewname);
            }
            catch (Exception ex)
            {
                //return View("ProjectInfoCheckListInsert", smodel);
                return RedirectToAction("Display_ProjectRegistrationDetails");
            }
        }

