        //Lock-Unlock Handler (Project Documents List)
        public JsonResult LockUnlockHandler_ProjectDocumentList(string parmProjectId, string parmLockUnlock, string parmPromoterID)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 PromoterCode = 0;
                Int32 IsDraftCode = 0;
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedLockUnlockMsg = string.Empty;

                if (parmProjectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(parmProjectId);
                }
                if (parmLockUnlock != string.Empty)
                {
                    IsDraftCode = Convert.ToInt32(parmLockUnlock);
                }
                if (parmPromoterID != string.Empty)
                {
                    PromoterCode = Convert.ToInt32(parmPromoterID);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project document(s) list details";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
