        [HttpPost]
        public ActionResult SearchProjectSpecialBankAccountDetail(ClsPrp_AuthDesk_View_ProjectSpecialBankAccountDetails[] numberobject)
        {
            bool status = false;
            Int64? chkappid = null;

            string UID = User.Identity.GetUserId();
            string UserNam = User.Identity.Name;

            ClsPrp_AuthDesk_View_ProjectSpecialBankAccountDetails aa = new ClsPrp_AuthDesk_View_ProjectSpecialBankAccountDetails();
            ClsMethod_View_ProjectSpecialBankAccountDetails sdbspan = new ClsMethod_View_ProjectSpecialBankAccountDetails();

            if (numberobject != null)
            {
                foreach (var item in numberobject)
                {
                    string prmSpecialBankAccountNumber = string.Empty;
                    string prmBankIFSCcode = string.Empty;
                    string prmPatternMatchBankAccountNumber = string.Empty;
                    Int32 prmSearchOptionFlag = 0;

                    //Object Value (Input)
                    prmSpecialBankAccountNumber = Convert.ToString(item.prmSpecialBankAccountNumber_Input);
                    prmBankIFSCcode = Convert.ToString(item.prmBankIFSCcode_Input);
                    prmPatternMatchBankAccountNumber = Convert.ToString(item.prmPatternMatchBankAccountNumber_Input);
                    prmSearchOptionFlag = Convert.ToInt32(item.prmSearchOption_Input);

                    aa.prpongoing = sdbspan.Extract_AuthDesk_ProjectSpecialBankAccountDetails_ByID(prmSpecialBankAccountNumber, prmBankIFSCcode, prmPatternMatchBankAccountNumber, prmSearchOptionFlag, UserNam);
                    chkappid = 1;
                }
            }

            if (chkappid == null)
                status = false;
            else
                status = true;

            return new JsonResult
            {
                Data = new
                {
                    status = status,
                    numberObject = aa.prpongoing
                }
            };
        }
