        //Lock-Unlock Handler (Land Details)
        public JsonResult LockUnlockHandler_ProjectRegistrationApplicationFee(string parmProjectId, string parmLockUnlock, string parmIndexID)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 IndexID = 0;
                Int32 IsDraftCode = 0;
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedLockUnlockMsg = string.Empty;

                if (parmProjectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(parmProjectId);
                }
                if (parmLockUnlock != string.Empty)
                {
                    IsDraftCode = Convert.ToInt32(parmLockUnlock);
                }
                if (parmIndexID != string.Empty)
                {
                    IndexID = Convert.ToInt32(parmIndexID);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project registration application fee details";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
                        break;
                    case 5:
                        RelatedLockUnlockMsg = "Lock request";
                        break;
                    default:
                        RelatedLockUnlockMsg = "others";
                        break;
                }
                #endregion

                ClsMethod_View_ProjectRegistration sdb = new ClsMethod_View_ProjectRegistration();
                retvalueLockUnlock = sdb.Update_LockUnLockHandler_Project_RegistrationApplicationFee(ProjectCode, IndexID, IsDraftCode, userName, userID, RelatedRemarksIfAny, RelatedLockUnlockMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsDraft = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsDraft == 1)
                {
                    parmStatusCode = 101;
                    parmStatus = "Successfully locked registration application fee details.";
                }
                else if (IsDraft == 5)
                {
                    parmStatusCode = 105;
                    parmStatus = "Successfully un-locked registration application fee details.";
                }
                else if (IsDraft == 6)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
