        [HttpGet]
        public ActionResult PromoterExtractRelatedLinksJointPromoterDetails(Int64 projectId, Int64 promoterId, Int64 linkpromoterId, Int64 jpromoterapplicationId, Int32 jpromoterapplicationType, Int32 varflag)
        {
            string UserName = string.Empty;
            string userRole = string.Empty;
            Int64 prmProjectId = 0;
            Int64 prmPromoterID = 0;
            Int64 putPromoterID = 0;
            Int64 prmLinkPromoterId = 0;
            Int64 prmJPromoterApplicationId = 0;
            Int64 prmJPromoterApplicationType = 0;
            Int32 prmFlag = 0;

            prmProjectId = projectId;
            prmPromoterID = promoterId;
            prmLinkPromoterId = linkpromoterId;
            prmJPromoterApplicationId = jpromoterapplicationId;
            prmJPromoterApplicationType = jpromoterapplicationType;
            prmFlag = varflag;

            UserName = User.Identity.Name;
            userRole = getUserRole();

            if (Session["zipProjectDiaryNumber"] != null)
            {
                Int64? Promoter_ID = Convert.ToInt64(Session["zipPromoterID"]);
                putPromoterID = (Promoter_ID != null) ? Convert.ToInt64(Promoter_ID) : 0;
            }

            ClsMethodDistrictMaster objdis = new ClsMethodDistrictMaster();
            ClsPrp_PromoterLinksJointPromoterIndividualForm objprpIND = new ClsPrp_PromoterLinksJointPromoterIndividualForm();
            ClsPrp_PromoterLinksJointPromoterOrgExpForm objOTIprp = new ClsPrp_PromoterLinksJointPromoterOrgExpForm();
            ClsMethod_PromoterLinksJointPromoterOrgExpForm objDB = new ClsMethod_PromoterLinksJointPromoterOrgExpForm();
            ClsMethod_View_PromoterDocuments objdocDB = new ClsMethod_View_PromoterDocuments();

            int? statecode;
            int? DistrictCode;
            int? BusinessPlace_AddressStateCode;
            int? BusinessPlace_AddressDistrictCode;

            object objRtn = null;
            string viewRtn = string.Empty;

            try
            {
                switch (prmJPromoterApplicationType)
                {
                    case 1:
                        {
                            objprpIND = objDB.DisplayIndPro(Convert.ToInt64(prmLinkPromoterId));

                            statecode = Convert.ToInt32(objprpIND.State);
                            objprpIND.State = objdis.State_Name(statecode);

                            DistrictCode = Convert.ToInt32(objprpIND.District);
                            objprpIND.District = objdis.District_Name(DistrictCode);

                            objprpIND.prpLitigations = objDB.DisplayLitigationn(prmLinkPromoterId);
                            objprpIND.prpongoing = objDB.DisplaybyID_ongoingProject(prmLinkPromoterId);
                            objprpIND.promoterDoc = objdocDB.Display_AuthDesk_Promoter_Documents_PromoterId(prmLinkPromoterId);

                            objRtn = objprpIND;
                            viewRtn = "PromoterExtractRelatedLinksJointPromoterIndividualDetails";
                        }
                        break;
                    case 2:
                        {
                            objOTIprp = objDB.DisplayOrgExp(Convert.ToInt64(prmLinkPromoterId));

                            statecode = Convert.ToInt32(objOTIprp.Org_State);
                            objOTIprp.Org_State = objdis.State_Name(statecode);

                            DistrictCode = Convert.ToInt32(objOTIprp.Org_District);
                            objOTIprp.Org_District = objdis.District_Name(DistrictCode);

                            BusinessPlace_AddressStateCode = Convert.ToInt32(objOTIprp.State);
                            objOTIprp.State = objdis.State_Name(BusinessPlace_AddressStateCode);

                            BusinessPlace_AddressDistrictCode = Convert.ToInt32(objOTIprp.District);
                            objOTIprp.District = objdis.District_Name(BusinessPlace_AddressDistrictCode);

                            objOTIprp.Prpparententity = objDB.DisplayDetailByApplicationID(prmLinkPromoterId);
                            for (var h = 0; h < objOTIprp.Prpparententity.Count; h++)
                            {
                                Int32? strDistrictCode = Convert.ToInt32(objOTIprp.Prpparententity[h].District);
                                objOTIprp.Prpparententity[h].District = objdis.District_Name(strDistrictCode);

                                Int32? strstatecode = Convert.ToInt32(objOTIprp.Prpparententity[h].State);
                                objOTIprp.Prpparententity[h].State = objdis.State_Name(strstatecode);
                            }

                            objOTIprp.prpMem = objDB.Display_MemProject(prmLinkPromoterId);
                            for (var i = 0; i < objOTIprp.prpMem.Count; i++)
                            {
                                Int32? strDistrictCode = Convert.ToInt32(objOTIprp.prpMem[i].District);
                                objOTIprp.prpMem[i].District = objdis.District_Name(strDistrictCode);

                                Int32? strstatecode = Convert.ToInt32(objOTIprp.prpMem[i].State);
                                objOTIprp.prpMem[i].State = objdis.State_Name(strstatecode);
                            }

                            objOTIprp.prpLitigations = objDB.DisplayLitigationn(prmLinkPromoterId);
                            objOTIprp.prpongoing = objDB.DisplaybyID_ongoingProject(prmLinkPromoterId);
                            objOTIprp.promoterDoc = objdocDB.Display_AuthDesk_Promoter_Documents_PromoterId(prmLinkPromoterId);

                            objRtn = objOTIprp;
                            viewRtn = "PromoterExtractRelatedLinksJointPromoterDetails";
                        }
                        break;
                    default:
                        {
                            objRtn = objprpIND;
                            viewRtn = "PromoterExtractRelatedLinksJointPromoterIndividualDetails";
                        }
                        break;
                }
            }
            catch (Exception ex)
            {
                string strRn = ex.ToString();
            }
            return View(viewRtn, objRtn);
        }

        //Lock-Unlock Handler (Promoter Ind Profile)
        public JsonResult LockUnlockHandler_PromoterIndividualProfile(string parmProjectId, string parmPromoterId, string parmLockUnlock, string parmIndexID)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 PromoterCode = 0;
                Int64 IndexID = 0;
                Int32 IsDraftCode = 0;
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedLockUnlockMsg = string.Empty;

                if (parmProjectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(parmProjectId);
                }
                if (parmPromoterId != string.Empty)
                {
                    PromoterCode = Convert.ToInt64(parmPromoterId);
                }
                if (parmLockUnlock != string.Empty)
                {
                    IsDraftCode = Convert.ToInt32(parmLockUnlock);
                }
                if (parmIndexID != string.Empty)
                {
                    IndexID = Convert.ToInt32(parmIndexID);
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Promoter profile (individual) details";
                switch (IsDraftCode)
                {
                    case 1:
                        RelatedLockUnlockMsg = "Unlock request";
                        break;
                    case 5:
                        RelatedLockUnlockMsg = "Lock request";
                        break;
                    default:
                        RelatedLockUnlockMsg = "others";
                        break;
                }
                #endregion
                ClsPromoterPrintForm sdb = new ClsPromoterPrintForm();
                retvalueLockUnlock = sdb.Update_LockUnLockHandler_Promoter_IndividualProfileDetails(ProjectCode, PromoterCode, IndexID, IsDraftCode, userName, userID, RelatedRemarksIfAny, RelatedLockUnlockMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsDraft = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsDraft == 1)
                {
                    parmStatusCode = 101;
                    parmStatus = "Successfully locked promoter profile (individual) details.";
                }
                else if (IsDraft == 5)
                {
                    parmStatusCode = 105;
                    parmStatus = "Successfully un-locked promoter profile (individual) details.";
                }
                else if (IsDraft == 6)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid lock-Unlock Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

