        [HttpGet]
        public ActionResult ProjectQUpdatesInfoDeskRecordsDetails()
        {
            var today = DateTime.Today;

            int quarter = ((today.Month - 1) / 3) + 1;

            DateTime quarterStart = new DateTime(today.Year, ((quarter - 1) * 3) + 1, 1);
            DateTime quarterEnd = quarterStart.AddMonths(3).AddDays(-1);

            return BindProjectQUpdatesInfoDeskRecordsDetails(today.Year, quarterStart, quarterEnd, "daterange", "This Quarter");
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult ProjectQUpdatesInfoDeskRecordsDetails(int? approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            return BindProjectQUpdatesInfoDeskRecordsDetails(approvalyear, fromDate, toDate, filterType, rangeLabel);
        }

        private ActionResult BindProjectQUpdatesInfoDeskRecordsDetails(int? approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            ClsMethod_View_QuarterlyUpdatesProjectsDetails sdb = new ClsMethod_View_QuarterlyUpdatesProjectsDetails();
            ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetails aa = new ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetails();
            ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetailsToExcel aaXls = new ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetailsToExcel();

            string userRole = string.Empty;
            // aa.prpongoing = sdb.Display_AuthDesk_QuarterlyUpdatesProjectsDiaryNumberDetails_ByUserID(userRole);
            aa.prpongoing = sdb.Display_AuthDesk_QuarterlyUpdatesProjectsDiaryNumberDetails_ByDate(approvalyear, fromDate, toDate, filterType, userRole);


            foreach (var item in aa.prpongoing)
            {
                ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetailsToExcel aaXlsInner = new ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetailsToExcel();

                aaXlsInner.Diary_Number = item.QUpdateProject_RegDiaryNumber_Name;
                aaXlsInner.Application_Date = item.QUpdatesApplication_Date;
                aaXlsInner.Project_DiaryNumber = item.ProjectRegDiaryNumber_Name;
                aaXlsInner.RERA_Registration_Number = item.RERAregistrationnumber;
                aaXlsInner.RERA_Number_IssueDate = item.RERAnumberIssueDate;
                aaXlsInner.RERA_Number_RegistrationUptoDate = item.RERAnumberValidUptoDate;
                aaXlsInner.Quarter_Year = item.setQuarterValue_Year;
                aaXlsInner.Quarter_Title = item.setQuarterValue_Name;
                aaXlsInner.Project_Name = item.Project_Name;
                aaXlsInner.Promoter_Name = item.Promoter_Name;
                aaXlsInner.Project_AddressDistrict = item.Project_AddressDistrictName;
                aaXlsInner.Status_Title = item.EventAction_Aggregate;
                aaXlsInner.Status = item.EventRemarks_IfAny;
                aaXlsInner.Status_Date = item.EventAction_IdentifiedOn;
                aaXls.prpongoing.Add(aaXlsInner);
            }
            Session["modelQUpdatesProjectsInPublicViewMIS"] = aaXls.prpongoing;
            ViewBag.Years = GetApprovalYears();
            ViewBag.SelectedApprovalYear = approvalyear;
            ViewBag.FromDate = fromDate.HasValue ? fromDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.ToDate = toDate.HasValue ? toDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.SelectedRangeLabel = rangeLabel ?? string.Empty;
            ModelState.Clear();
            return View("ProjectQUpdatesInfoDeskRecordsDetails", aa);
        }



        public void QuarterlyUpdatesProjectsInPublicView_ExportToExcel()
        {
            var objXlslist = Session["modelQUpdatesProjectsInPublicViewMIS"] as List<ClsPrp_AuthorityDesk_QUpdatesProjectRecordsDetailsToExcel>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");
            workSheet.TabColor = System.Drawing.Color.Black;
            workSheet.DefaultRowHeight = 12;

            //Header of table
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "Registration Number";
            workSheet.Cells[1, 3].Value = "Registration Issue Date";
            workSheet.Cells[1, 4].Value = "Registration Valid Upto Date";
            workSheet.Cells[1, 5].Value = "Diary Number";
            workSheet.Cells[1, 6].Value = "Application Date";
            workSheet.Cells[1, 7].Value = "Project Diary Number";
            workSheet.Cells[1, 8].Value = "Latest Quarter Year";
            workSheet.Cells[1, 9].Value = "Latest Quarter Name";
            workSheet.Cells[1, 10].Value = "Project Name";
            workSheet.Cells[1, 11].Value = "Promoter Name";
            workSheet.Cells[1, 12].Value = "Project District Name";
            workSheet.Cells[1, 13].Value = "Status";
            workSheet.Cells[1, 14].Value = "Status Date";
            workSheet.Cells[1, 15].Value = "Remarks, if Any";

            //Body of table  
            int recordIndex = 2;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.RERA_Registration_Number;
                workSheet.Cells[recordIndex, 3].Value = QRcodeItem.RERA_Number_IssueDate.HasValue ? (QRcodeItem.RERA_Number_IssueDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.RERA_Number_IssueDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                workSheet.Cells[recordIndex, 4].Value = QRcodeItem.RERA_Number_RegistrationUptoDate.HasValue ? (QRcodeItem.RERA_Number_RegistrationUptoDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.RERA_Number_RegistrationUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.Diary_Number;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.Application_Date.HasValue ? QRcodeItem.Application_Date.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.Project_DiaryNumber;
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.Quarter_Year;
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.Quarter_Title;
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.Project_Name;
                workSheet.Cells[recordIndex, 11].Value = QRcodeItem.Promoter_Name;
                workSheet.Cells[recordIndex, 12].Value = QRcodeItem.Project_AddressDistrict;
                workSheet.Cells[recordIndex, 13].Value = QRcodeItem.Status_Title;
                workSheet.Cells[recordIndex, 14].Value = QRcodeItem.Status_Date.HasValue ? QRcodeItem.Status_Date.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 15].Value = QRcodeItem.Status;

                workSheet.Row(recordIndex).Height = 15;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();
            workSheet.Column(13).AutoFit();
            workSheet.Column(14).AutoFit();
            workSheet.Column(15).AutoFit();

            workSheet.Cells["A1:O1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:O1"].Style.Fill.BackgroundColor.SetColor(ColorTranslator.FromHtml("#7bb73f"));

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 15])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofQuarterlyUpdateProjectsInPublicView_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }
