        //Public-Unpublic Handler (Audited Annual Report On Statement of Accounts By Index)
        public JsonResult PublicUnpublicHandler_ProjectQUpdatesAAReportOnStatementAccountsByIndex(string prmprojectId, string prmprojectformfiveindexId, string prmprojectformfiveId, string prmPublicUnpublic)
        {
            Int32 retvaluePublicUnpublic = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 ProjectFormFiveIndexCode = 0;
                Int32 ProjectFormFiveCode = 0;
                Int32 PublicUnpublicCode = 1; //Yes Public View
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmprojectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(prmprojectId);
                }
                if (prmprojectformfiveindexId != string.Empty)
                {
                    ProjectFormFiveIndexCode = Convert.ToInt32(prmprojectformfiveindexId);
                }
                if (prmprojectformfiveId != string.Empty)
                {
                    ProjectFormFiveCode = Convert.ToInt32(prmprojectformfiveId);
                }
                if (prmPublicUnpublic != string.Empty)
                {
                    if (prmPublicUnpublic == "true")
                    {
                        // has class YPV, request for UnPublicView. hence set NPV
                        PublicUnpublicCode = 2; //("NPV");
                    }
                    else if (prmPublicUnpublic == "false")
                    {
                        // has class NPV, request for PublicView. hence set YPV
                        PublicUnpublicCode = 1; //("YPV");
                    }
                    else
                    {
                        // has class unknown, request for PublicView. hence set YPV
                        PublicUnpublicCode = 1; //("YPV");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project Audited Annual Report On Statement of Accounts details";
                switch (PublicUnpublicCode)
                {
                    case 2:
                        RelatedPVMsg = "UnPublicView request";
                        break;
                    case 1:
                        RelatedPVMsg = "PublicView request";
                        break;
                    default:
                        RelatedPVMsg = "others (PublicView)";
                        break;
                }
                #endregion
                ClsMethod_View_QuarterlyUpdatesProjectStatementAccountsFormFive sdb = new ClsMethod_View_QuarterlyUpdatesProjectStatementAccountsFormFive();
                retvaluePublicUnpublic = sdb.Update_PublicUnpublicHandler_QuarterlyUpdatesProject_FormFiveDetailsByIndex(ProjectCode, ProjectFormFiveIndexCode, ProjectFormFiveCode, PublicUnpublicCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvaluePublicUnpublic; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Enabled successfully public view of Audited Annual Report On Statement of Accounts.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Disabled successfully public view of Audited Annual Report On Statement of Accounts.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
