        //Public-Unpublic Handler (Status Of Approvals By Index)
        public JsonResult PublicUnpublicHandler_ProjectQUpdatesStatusOfApprovalsByIndex(string prmprojectId, string prmprojectapprovalsindexId, string prmprojectapprovalsId, string prmPublicUnpublic)
        {
            Int32 retvaluePublicUnpublic = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 ProjectApprovalsIndexCode = 0;
                Int32 ProjectApprovalsCode = 0;
                string PublicUnpublicCode = "YPV"; //Yes Public View
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmprojectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(prmprojectId);
                }
                if (prmprojectapprovalsindexId != string.Empty)
                {
                    ProjectApprovalsIndexCode = Convert.ToInt32(prmprojectapprovalsindexId);
                }
                if (prmprojectapprovalsId != string.Empty)
                {
                    ProjectApprovalsCode = Convert.ToInt32(prmprojectapprovalsId);
                }
                if (prmPublicUnpublic != string.Empty)
                {
                    if (prmPublicUnpublic == "true")
                    {
                        // has class YPV, request for UnPublicView. hence set NPV
                        PublicUnpublicCode = Convert.ToString("NPV");
                    }
                    else if (prmPublicUnpublic == "false")
                    {
                        // has class NPV, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                    else
                    {
                        // has class unknown, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project status of approvals details";
                switch (PublicUnpublicCode)
                {
                    case "NPV":
                        RelatedPVMsg = "UnPublicView request";
                        break;
                    case "YPV":
                        RelatedPVMsg = "PublicView request";
                        break;
                    default:
                        RelatedPVMsg = "others (PublicView)";
                        break;
                }
                #endregion
                ClsMethod_View_QuarterlyUpdatesProjectApprovals sdb = new ClsMethod_View_QuarterlyUpdatesProjectApprovals();
                retvaluePublicUnpublic = sdb.Update_PublicUnpublicHandler_QuarterlyUpdatesProject_StatusOfApprovalsByIndex(ProjectCode, ProjectApprovalsIndexCode, ProjectApprovalsCode, PublicUnpublicCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvaluePublicUnpublic; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Enabled successfully public view of status of approvals.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Disabled successfully public view of status of approvals.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
        #endregion

