                if (prmprojectexternalfacilitiesindexId != string.Empty)
                {
                    ProjectExternalFacilitiesIndexCode = Convert.ToInt32(prmprojectexternalfacilitiesindexId);
                }
                if (prmprojectexternalfacilitiesId != string.Empty)
                {
                    ProjectExternalFacilitiesCode = Convert.ToInt32(prmprojectexternalfacilitiesId);
                }
                if (prmPublicUnpublic != string.Empty)
                {
                    if (prmPublicUnpublic == "true")
                    {
                        // has class YPV, request for UnPublicView. hence set NPV
                        PublicUnpublicCode = Convert.ToString("NPV");
                    }
                    else if (prmPublicUnpublic == "false")
                    {
                        // has class NPV, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                    else
                    {
                        // has class unknown, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project status of external facilities details";
                switch (PublicUnpublicCode)
                {
                    case "NPV":
                        RelatedPVMsg = "UnPublicView request";
                        break;
                    case "YPV":
                        RelatedPVMsg = "PublicView request";
                        break;
                    default:
                        RelatedPVMsg = "others (PublicView)";
                        break;
                }
                #endregion
                ClsMethod_View_QuarterlyUpdatesProjectStatusExternalFacilities sdb = new ClsMethod_View_QuarterlyUpdatesProjectStatusExternalFacilities();
                retvaluePublicUnpublic = sdb.Update_PublicUnpublicHandler_QuarterlyUpdatesProject_StatusOfExternalFacilitiesByIndex(ProjectCode, ProjectExternalFacilitiesIndexCode, ProjectExternalFacilitiesCode, PublicUnpublicCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvaluePublicUnpublic; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Enabled successfully public view of status of external facilities.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Disabled successfully public view of status of external facilities.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
        #endregion

