        [HttpGet]
        public ActionResult ProjectCompletionInfoDeskApproved()
        {
            return BindProjectCompletionInfoDeskApproved(DateTime.Now.Year, null, null, "year", string.Empty);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult ProjectCompletionInfoDeskApproved(int approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            return BindProjectCompletionInfoDeskApproved(approvalyear, fromDate, toDate, filterType, rangeLabel);
        }

        private ActionResult BindProjectCompletionInfoDeskApproved(int approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            ClsMethod_View_CompletionCertificateHelpdesk sdb = new ClsMethod_View_CompletionCertificateHelpdesk();
            ClsPrp_AuthorityDesk_CompletionCertificateDiaryNumber aa = new ClsPrp_AuthorityDesk_CompletionCertificateDiaryNumber();
            ClsPrp_AuthorityDesk_CompletionCertificateDiaryNumberToExcel aaXls = new ClsPrp_AuthorityDesk_CompletionCertificateDiaryNumberToExcel();

            string userRole = string.Empty;
            //aa.prpongoing = sdb.Display_AuthorityDesk_ProjectCompletionDetailsApproved(userRole);
            aa.prpongoing = sdb.Display_AuthorityDesk_ProjectCompletionDetailsApprovedByDate(approvalyear, filterType, fromDate, toDate, userRole);
            foreach (var item in aa.prpongoing)
            {
                ClsPrp_AuthorityDesk_CompletionCertificateDiaryNumberToExcel aaXlsInner = new ClsPrp_AuthorityDesk_CompletionCertificateDiaryNumberToExcel();
                aaXlsInner.Project_RERAregistrationNumber = item.Project_RERAregistrationNumber;
                aaXlsInner.Project_RERAregistrationIssueDate = item.Project_RERAregistrationIssueDate;
                aaXlsInner.Project_RERAregistrationValidUptoDate = item.Project_RERAregistrationValidUptoDate;
                aaXlsInner.Project_RERAextnregistrationValidUptoDate = item.Project_RERAextnregistrationValidUptoDate;
                aaXlsInner.PCC_RegDiaryNumber_Name = item.PCC_RegDiaryNumber_Name;
                aaXlsInner.Project_DiaryNumber = item.Project_DiaryNumber;
                aaXlsInner.ProjectCompletionApplicationDate = item.ProjectCompletionApplicationDate;
                aaXlsInner.Project_Name = item.Project_Name;
                aaXlsInner.Project_AddressDistrictName = item.Project_AddressDistrictName;
                aaXlsInner.Promoter_Name = item.Promoter_Name;
                aaXlsInner.EventAction_Aggregate = item.EventAction_Aggregate;
                aaXlsInner.EventAction_IdentifiedOn = item.EventAction_IdentifiedOn;
                aaXls.prpongoing.Add(aaXlsInner);
            }
            Session["modelApprovedCompletionApplicationsforProjectMIS"] = aaXls.prpongoing;
            ViewBag.Years = GetApprovalYears();
            ViewBag.SelectedApprovalYear = approvalyear;
            ViewBag.FromDate = fromDate.HasValue ? fromDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.ToDate = toDate.HasValue ? toDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.SelectedRangeLabel = rangeLabel ?? string.Empty;
            ModelState.Clear();
            return View("ProjectCompletionInfoDeskApproved", aa);
        }

