                    workSheet.Cells[recordIndex, 3].Value = QRcodeItem.Project_RERAregistrationIssueDate.HasValue ? (QRcodeItem.Project_RERAregistrationIssueDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.Project_RERAregistrationIssueDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                    workSheet.Cells[recordIndex, 4].Value = QRcodeItem.Project_RERAregistrationValidUptoDate.HasValue ? (QRcodeItem.Project_RERAregistrationValidUptoDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.Project_RERAregistrationValidUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                }
                else
                {
                    workSheet.Cells[recordIndex, 3].Value = string.Empty;
                    workSheet.Cells[recordIndex, 4].Value = string.Empty;
                }
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.Project_RERAextnregistrationValidUptoDate.HasValue ? (QRcodeItem.Project_RERAextnregistrationValidUptoDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.Project_RERAextnregistrationValidUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.Project_DiaryNumber;
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.PCC_RegDiaryNumber_Name;
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.ProjectCompletionApplicationDate.HasValue ? (QRcodeItem.ProjectCompletionApplicationDate.Value.ToString("dd-MMM-yyyy") != "01-Jan-0001" ? QRcodeItem.ProjectCompletionApplicationDate.Value.ToString("dd-MMM-yyyy") : string.Empty) : string.Empty;
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.Project_Name;
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.Project_AddressDistrictName;
                workSheet.Cells[recordIndex, 11].Value = QRcodeItem.Promoter_Name;
                workSheet.Cells[recordIndex, 12].Value = QRcodeItem.EventAction_Aggregate;
                workSheet.Cells[recordIndex, 13].Value = QRcodeItem.EventAction_IdentifiedOn.HasValue ? QRcodeItem.EventAction_IdentifiedOn.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 14].Value = string.Empty;

                workSheet.Row(recordIndex).Height = 15;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();
            workSheet.Column(13).AutoFit();
            workSheet.Column(14).AutoFit();

            workSheet.Cells["A1:N1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:N1"].Style.Fill.BackgroundColor.SetColor(ColorTranslator.FromHtml("#7bb73f"));

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 14])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofPublicViewCertificateforProjectCompletions_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }
