        [HttpGet]
        public ActionResult Add_CompletionProjectRegistrationNumber()
        {
            ClsPrp_AuthorityDesk_CompletionProjectRegistrationNumber aa = new ClsPrp_AuthorityDesk_CompletionProjectRegistrationNumber();
            ClsMethod_View_CompletionCertificateProjectNumber sdb = new ClsMethod_View_CompletionCertificateProjectNumber();
            ClsMethodDistrictMaster objdis = new ClsMethodDistrictMaster();

            Int64 ccProjectID = 0;
            Int64 ccPromoterID = 0;
            DateTime? ccLastmodifiedDate = DateTime.Now;
            string ccProjectName = string.Empty;
            string ccProjectDiaryNumber = string.Empty;
            string ccCompletionDiaryNumber = string.Empty;
            string ccRegistrationNumber = string.Empty;

            string userRole = string.Empty;
            userRole = getUserRole();

            if (Session["zipPCCprojectCompletionDiaryNumber"] != null)
            {
                string PCCprojectCompletionDiaryNumber = Session["zipPCCprojectCompletionDiaryNumber"].ToString();
                string PCCprojectProjectDiaryNumber = Session["zipPCCprojectProjectDiaryNumber"].ToString();
                string PCCprojectProjectName = Session["zipPCCprojectProjectName"].ToString();
                Int64? PCCprojectProjectID = Convert.ToInt64(Session["zipPCCprojectProjectID"]);
                DateTime? PCCprojectLastModifiedOn = Convert.ToDateTime(Session["zipPCCprojectLastModifiedOn"]);
                Int64? PCCprojectPromoterID = Convert.ToInt64(Session["zipPCCprojectPromoterID"]);
                string PCCprojectProjectRegistrationNumber = Session["zipPCCprojectProjectRegistrationNumber"].ToString();

                ccPromoterID = (PCCprojectPromoterID != null) ? Convert.ToInt64(PCCprojectPromoterID) : 0;
                ccProjectID = (PCCprojectProjectID != null) ? Convert.ToInt64(PCCprojectProjectID) : 0;
                ccCompletionDiaryNumber = (String.IsNullOrEmpty(PCCprojectCompletionDiaryNumber) ? "" : PCCprojectCompletionDiaryNumber);
                ccProjectDiaryNumber = (String.IsNullOrEmpty(PCCprojectProjectDiaryNumber) ? "" : PCCprojectProjectDiaryNumber);
                ccProjectName = (String.IsNullOrEmpty(PCCprojectProjectName) ? "" : PCCprojectProjectName);
                ccLastmodifiedDate = PCCprojectLastModifiedOn;
                ccRegistrationNumber = (String.IsNullOrEmpty(PCCprojectProjectRegistrationNumber) ? "" : PCCprojectProjectRegistrationNumber);
            }

