        [HttpPost]
        public ActionResult ProjectRevokeInfoEventInsert(ClsPrp_AuthorityDesk_RevocationCancellationProjectEventLog smodel)
        {
            ClsPrp_AuthorityDesk_RevocationCancellationProjectEventLog aa = new ClsPrp_AuthorityDesk_RevocationCancellationProjectEventLog();
            try
            {
                if (ModelState.IsValid)
                {
                    ClsMethod_View_RevocationCancellationHelpdesk sdb = new ClsMethod_View_RevocationCancellationHelpdesk();
                    string pUserRole = string.Empty;
                    pUserRole = getUserRole();
                    string pUser_WhoIdentified = User.Identity.Name;

                    if (sdb.Add_ProjectRevocationCancellation_InfoEvent(smodel, pUserRole, pUser_WhoIdentified))
                    {
                        ViewBag.Message = "Details Added Successfully";
                        ModelState.Clear();

                        TempData["RevokeEventSubmitMessage"] = "Application Performa successfully Submitted.";
                        TempData["RevokeEventSubmitMessageMappingUrlFlag"] = getMappingUrlByProjectRevokeEvent();
                    }

                    //to bind subCheckList master
                    aa.EventMaster = sdb.Display_AuthorityDesk_ProjectRevokeEvent_Master(pUserRole);

                    if (Session["zipRevokeProjectRevokeDiaryNumber"] != null)
                    {
                        string RevokeProjectRevokeDiaryNumber = Session["zipRevokeProjectRevokeDiaryNumber"].ToString();
                        string RevokeProjectDiaryNumber = Session["zipRevokeProjectDiaryNumber"].ToString();
                        string RevokeProjectName = Session["zipRevokeProjectName"].ToString();
                        Int64? RevokeProjectID = Convert.ToInt64(Session["zipRevokeProjectID"]);
                        DateTime? RevokeProjectLastModifiedOn = Convert.ToDateTime(Session["zipRevokeProjectLastModifiedOn"]);
                        Int64? RevokePromoterID = Convert.ToInt64(Session["zipRevokeProjectPromoterID"]);
                        string RevokeProjectRegistrationNumber = Session["zipRevokeProjectRegistrationNumber"].ToString();

                        aa.Related_Promoter_ID = (RevokePromoterID != null) ? Convert.ToInt64(RevokePromoterID) : 0;
                        aa.Related_Project_ID = (RevokeProjectID != null) ? Convert.ToInt64(RevokeProjectID) : 0;
                        aa.Revoke_DiaryNumber = (String.IsNullOrEmpty(RevokeProjectRevokeDiaryNumber) ? "" : RevokeProjectRevokeDiaryNumber);
                        aa.Project_DiaryNumber = (String.IsNullOrEmpty(RevokeProjectDiaryNumber) ? "" : RevokeProjectDiaryNumber);
                        aa.ProjectName = (String.IsNullOrEmpty(RevokeProjectName) ? "" : RevokeProjectName);
                        aa.ProjectLastModifiedOn = RevokeProjectLastModifiedOn;
                        aa.ProjectRegistrationNumberName = (String.IsNullOrEmpty(RevokeProjectRegistrationNumber) ? "" : RevokeProjectRegistrationNumber);
                    }
                    else
                    {
                        aa.Related_Promoter_ID = 0;
                        aa.Related_Project_ID = 0;
                        aa.Revoke_DiaryNumber = string.Empty;
                        aa.Project_DiaryNumber = string.Empty;
                        aa.ProjectName = string.Empty;
                        aa.ProjectLastModifiedOn = DateTime.Now;
                        aa.ProjectRegistrationNumberName = string.Empty;
                    }
                }
                return View("ProjectRevokeInfoEventInsert", aa);
            }
            catch (Exception ex)
            {
                string strret = ex.ToString();
                TempData["RevokeEventSubmitMessage"] = "Sorry, Application Performa is pending";
                TempData["RevokeEventSubmitMessageMappingUrlFlag"] = getMappingUrlByProjectRevokeEvent();

                return View("ProjectRevokeInfoEventInsert", aa);
            }
        }

