        [HttpGet]
        public ActionResult ProjectWorkFileInfoDeskApproved()
        {
            return BindProjectWorkFileInfoDeskApproved(DateTime.Now.Year, null, null, "year", string.Empty);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult ProjectWorkFileInfoDeskApproved(int approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            return BindProjectWorkFileInfoDeskApproved(approvalyear, fromDate, toDate, filterType, rangeLabel);
        }

        private ActionResult BindProjectWorkFileInfoDeskApproved(int approvalyear, DateTime? fromDate, DateTime? toDate, string filterType, string rangeLabel)
        {
            ClsMethod_View_ProjectWorkingFilesHelpdesk sdb = new ClsMethod_View_ProjectWorkingFilesHelpdesk();
            ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumber prpObj = new ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumber();
            ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumberToExcel prpObjXls = new ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumberToExcel();

            string userRole = string.Empty;
            userRole = User.Identity.GetUserId();
            //prpObj.prpongoing = sdb.Display_AuthorityDesk_ProjectWorkingFileDetailsApproved(userRole);
            prpObj.prpongoing = sdb.Display_AuthorityDesk_ProjectWorkingFileDetailsApprovedByDate(approvalyear, filterType, fromDate, toDate, userRole);

            foreach (var item in prpObj.prpongoing)
            {
                ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumberToExcel prpXlsInner = new ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumberToExcel();

                prpXlsInner.RERA_Registration_Number = item.RERAnumberRegistration;
                prpXlsInner.RERA_Number_IssueDate = item.RERAnumberIssueDate;
                prpXlsInner.RERA_Number_RegistrationUptoDate = item.RERAnumberRegUptoDate;
                prpXlsInner.Project_DiaryNumber = item.ProjectRegDiaryNumber_Name;
                prpXlsInner.Application_Date = item.ApplicationDate;
                prpXlsInner.Project_Name = item.Project_Name;
                prpXlsInner.Project_AddressDistrictName = item.Project_AddressDistrictName;
                prpXlsInner.ProjectPotentialZone = item.ProjectPotentialZone;
                prpXlsInner.ProjectWebLink = item.ProjectWebLink;
                prpXlsInner.Promoter_Name = item.Promoter_Name;
                prpXlsInner.PromoterType = item.PromoterType == 1 ? "Individual" : "Other Than Individual";
                prpXlsInner.Status = item.EventAction_Aggregate;
                prpXlsInner.Status_Date = item.EventAction_IdentifiedOn;
                prpObjXls.prpongoing.Add(prpXlsInner);
            }
            Session["modelApprovedWorkFilesforProjectMIS"] = prpObjXls.prpongoing;
            ViewBag.Years = GetApprovalYears();
            ViewBag.SelectedApprovalYear = approvalyear;
            ViewBag.FromDate = fromDate.HasValue ? fromDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.ToDate = toDate.HasValue ? toDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.SelectedRangeLabel = rangeLabel ?? string.Empty;
            ModelState.Clear();
            return View("ProjectWorkFileInfoDeskApproved", prpObj);
        }



