        private static void HydrateCoreRegistrationFields(
            ClsPrp_AuthorityDesk_ProjectDiaryNumber target,
            ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumber source)
        {
            if (target == null || source == null)
            {
                return;
            }

            if (string.IsNullOrWhiteSpace(target.EventAction_Aggregate) && !string.IsNullOrWhiteSpace(source.EventAction_Aggregate))
            {
                target.EventAction_Aggregate = source.EventAction_Aggregate;
            }

            if (!target.EventAction_IdentifiedOn.HasValue && source.EventAction_IdentifiedOn.HasValue)
            {
                target.EventAction_IdentifiedOn = source.EventAction_IdentifiedOn;
            }
        }

        private static void HydrateCertificateFields(
            ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumber target,
            ClsPrp_AuthorityDesk_ProjectWorkFileDiaryNumber source)
