            {
                return;
            }

            if (string.IsNullOrWhiteSpace(target.ProjectRERAcert_FilePath) && !string.IsNullOrWhiteSpace(source.ProjectRERAcert_FilePath))
            {
                target.ProjectRERAcert_FilePath = source.ProjectRERAcert_FilePath;
            }

            if (string.IsNullOrWhiteSpace(target.ProjectRERAcert_FileName) && !string.IsNullOrWhiteSpace(source.ProjectRERAcert_FileName))
            {
                target.ProjectRERAcert_FileName = source.ProjectRERAcert_FileName;
            }
        }

