                prpXlsInner.RERA_Number_IssueDate = item.RERAnumberIssueDate;
                prpXlsInner.RERA_Number_RegistrationUptoDate = item.RERAnumberRegUptoDate;
                prpXlsInner.Project_DiaryNumber = item.ProjectRegDiaryNumber_Name;
                prpXlsInner.Application_Date = item.ApplicationDate;
                prpXlsInner.Project_Name = item.Project_Name;
                prpXlsInner.Project_AddressDistrictName = item.Project_AddressDistrictName;
                prpXlsInner.ProjectPotentialZone = item.ProjectPotentialZone;
                prpXlsInner.ProjectWebLink = item.ProjectWebLink;
                prpXlsInner.Promoter_Name = item.Promoter_Name;
                prpXlsInner.PromoterType = item.PromoterType == 1 ? "Individual" : "Other Than Individual";
                prpXlsInner.Status = item.EventAction_Aggregate;
                prpXlsInner.Status_Date = item.EventAction_IdentifiedOn;
                prpObjXls.prpongoing.Add(prpXlsInner);
            }
            Session["modelPendingPublicViewWorkFilesforProjectMIS"] = prpObjXls.prpongoing;
            ViewBag.Years = GetApprovalYears();
            ViewBag.SelectedApprovalYear = approvalyear;
            ViewBag.FromDate = fromDate.HasValue ? fromDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.ToDate = toDate.HasValue ? toDate.Value.ToString("yyyy-MM-dd") : string.Empty;
            ViewBag.SelectedRangeLabel = rangeLabel ?? string.Empty;
            ModelState.Clear();
            return View("ProjectWorkFileInfoDeskPendingPublicView", prpObj);
        }

