        #region Registration history

        [HttpGet]
        public ActionResult Display_Project_RefRegistrations_RERA()
        {
            ClsPrp_AuthorityDesk_ProjectRERAnumberDiaryNumberRefHist aa = new ClsPrp_AuthorityDesk_ProjectRERAnumberDiaryNumberRefHist();
            ClsMethodDistrictMaster objdis = new ClsMethodDistrictMaster();

            ClsMethod_View_RenewalAgent_AgentOtherStateUT_RERA sdb = new ClsMethod_View_RenewalAgent_AgentOtherStateUT_RERA();
            //ClsPrp_AuthDesk_View_RenewalAgent_RefRegistration_RERA aa = new ClsPrp_AuthDesk_View_RenewalAgent_RefRegistration_RERA();

            string userRole = string.Empty;
            userRole = getUserRole();

            Int64 ProjectID = 0;
            Int64 PromoterID = 0;
            string ProjectDiaryNumber = "";
            string ProjectName = "";
            DateTime LastModifiedOn = DateTime.MinValue;

            if (Session["zipProjectDiaryNumber"] != null)
            {
                ProjectID = (Session["zipProjectID"] != null) ? Convert.ToInt64(Session["zipProjectID"]) : 0;
                PromoterID = (Session["zipPromoterID"] != null) ? Convert.ToInt64(Session["zipPromoterID"]) : 0;
                ProjectDiaryNumber = (Session["zipProjectDiaryNumber"] != null) ? Session["zipProjectDiaryNumber"].ToString() : "";
                ProjectName = (Session["zipProjectName"] != null) ? Session["zipProjectName"].ToString() : "";
                LastModifiedOn = Convert.ToDateTime(Session["zipLastModifiedOn"]);
            }

            aa.prpongoing = sdb.Display_AuthDesk_Project_RefRegistrations_RERADetail(ProjectID, PromoterID, ProjectDiaryNumber, ProjectName, userRole);
            if (Session["zipProjectDiaryNumber"] != null)
            {
                ProjectID = (Session["zipProjectID"] != null) ? Convert.ToInt64(Session["zipProjectID"]) : 0;
                PromoterID = (Session["zipPromoterID"] != null) ? Convert.ToInt64(Session["zipPromoterID"]) : 0;
                ProjectDiaryNumber = (Session["zipProjectDiaryNumber"] != null) ? Session["zipProjectDiaryNumber"].ToString() : "";
                ProjectName = (Session["zipProjectName"] != null) ? Session["zipProjectName"].ToString() : "";

                aa.zipRelated_Project_ID = Convert.ToInt64(ProjectID);
                aa.zipRelated_Promoter_ID = Convert.ToInt64(PromoterID);
                aa.zipProject_DiaryNumber = (ProjectDiaryNumber != null) ? Convert.ToString(ProjectDiaryNumber) : "";
                aa.zipProjectName = (ProjectName != null) ? Convert.ToString(ProjectName) : "";
                aa.zipProjectLastModifiedOn = LastModifiedOn;
            }

            return View("Display_Project_RefRegistrations_RERA", aa);
        }


        [HttpGet]
        public ActionResult ProjectInfo_PrevRegistrationsDetail(Int64 ProjectId, Int64 PromoterId, string DiaryNumber, string ProjectName, string flagCode, int DiaryNumberId)
        {
            ClsMethod_View_RenewalAgent_AgentOtherStateUT_RERA sdb = new ClsMethod_View_RenewalAgent_AgentOtherStateUT_RERA();
            ClsPrp_AuthorityDesk_ProjectRERAnumberDiaryNumberRefHist aa = new ClsPrp_AuthorityDesk_ProjectRERAnumberDiaryNumberRefHist();
            ClsMethodDistrictMaster objdis = new ClsMethodDistrictMaster();
            string userRole = string.Empty;
            userRole = getUserRole();

            int? statecode;
            int? DistrictCode;
            int? subDivisionCode;
            //int? BusinessPlace_AddressStateCode;
            //int? BusinessPlace_AddressDistrictCode;
            //int? BComm_AddressStateCode;
            //int? BComm_AddressDistrictCode;
            //int? BusinessPlace_AddressSubDivisionCode = 0;

            try
            {
                //aa.prpongoing = sdb.Display_PopUpDesk_Project_PrevRegistrationRecord_RERADetail(ProjectId,PromoterId,RefRegistrationID,flagCode,userRole);
                aa.prpongoing = sdb.Display_PopUpDesk_Project_PrevRegistrationRecord_RERADetail(ProjectId, PromoterId, DiaryNumber, ProjectName, flagCode, DiaryNumberId, userRole);

                foreach (var item in aa.prpongoing)
                {

                    // Project State
                    statecode = string.IsNullOrEmpty(item.ProjectAddressState) ? 0 : Convert.ToInt32(item.ProjectAddressState);
                    item.ProjectAddressState = objdis.State_Name(statecode);

                    // Project District
                    DistrictCode = string.IsNullOrEmpty(item.ProjectAddressDistrict) ? 0 : Convert.ToInt32(item.ProjectAddressDistrict);
                    item.ProjectAddressDistrict = objdis.District_Name(DistrictCode);

                    // SubDivision
                    subDivisionCode = string.IsNullOrEmpty(item.ProjectAddressSubDivision) ? 0 : Convert.ToInt32(item.ProjectAddressSubDivision);
                    item.ProjectAddressSubDivision = objdis.SubDivision_Name(subDivisionCode);

                    // Authorized Person State
                    statecode = string.IsNullOrEmpty(item.AuthorizedPerson_State) ? 0 : Convert.ToInt32(item.AuthorizedPerson_State);
                    item.AuthorizedPerson_State = objdis.State_Name(statecode);

                    // Authorized Person District
                    DistrictCode = string.IsNullOrEmpty(item.AuthorizedPerson_District) ? 0 : Convert.ToInt32(item.AuthorizedPerson_District);
                    item.AuthorizedPerson_District = objdis.District_Name(DistrictCode);
                }
            }
            catch (Exception ex)
            {
                string exSTR = ex.ToString();
            }
            return View("ProjectInfo_PrevRegistrationsDetail", aa);
        }


